if (typeof db !== 'undefined') {
  try {
    print("Inserting 150 hosts...");
    db.users.insertMany(hosts); // hosts collection doesn't exist? Wait, they used db.hosts earlier but maybe it was users. The code in seed-hosts-multiple-properties used db.hosts!
    const resH = db.hosts.insertMany(hosts);
    print("Hosts inserted:");
    print(resH.insertedCount);
    
    print("Inserting " + reviews.length + " reviews...");
    // make sure collection reviews exists 
    const resR = db.reviews.insertMany(reviews.map(r => {
      // transform date strings back to ISODate if applicable, but mongodb driver handles it loosely if it's string.
      r.createdAt = new ISODate(r.createdAt);
      r.updatedAt = new ISODate(r.updatedAt);
      return r;
    }));
    print("Reviews inserted:");
    print(resR.insertedCount);

  } catch (e) {
    print("Error:", e);
  }
}
